<?php
require_once __DIR__ . '/functions.php';
function product_card(array $p): void { ?>
<article class="product-card"><a class="product-visual" href="/product.php?id=<?=e($p['id'])?>" aria-label="View <?=e($p['name'])?>"><?php if($p['image']):?><img class="product-image" src="<?=e($p['image'])?>" alt="<?=e($p['name'])?> phone product view" width="320" height="320" loading="lazy"><?php else:?><div class="phone-art" role="img" aria-label="Illustrative phone placeholder"><span class="camera"></span><span class="lens l1"></span><span class="lens l2"></span><span class="lens l3"></span><span class="flash"></span></div><?php endif;?><span class="badge <?=$p['category']?>"><?=e($p['condition'])?></span></a><div class="product-info"><p class="eyebrow"><?=e($p['category']==='new'?'NEW IPHONES':'REFURBISHED')?></p><h3><a href="/product.php?id=<?=e($p['id'])?>"><?=e($p['name'])?></a></h3><p class="muted">From <?=e($p['storage'][0])?> · Demo inventory</p><div class="price-line"><s><?=money($p['original'])?></s><b><?=money($p['price'])?></b></div><div class="saving"><?=$p['discount']?>% OFF <span>Save <?=money($p['original']-$p['price'])?></span></div><form method="post" action="/cart.php"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=e($p['id'])?>"><input type="hidden" name="storage" value="<?=e($p['storage'][0])?>"><input type="hidden" name="color" value="Black"><button class="button button-dark full" type="submit">Add to bag</button></form></div></article>
<?php }
function product_grid(array $list): void { echo '<div class="product-grid">';foreach($list as $p)product_card($p);echo '</div>'; }
